// Level A2 modules of work.html (format in assets/js/work.js). Original dialogues and questions.
SECTIONS.extend("work", "a2", { items: [
  { id: "greet", t: { ar: "التحية في أول يوم في المكتب", en: "Greetings on your first day at the office" },
    body: { ar: "تقول أهلًا، وتعرّف اسمك وشغلك، وترد على اللي بيرحّب بيك. ركّز على **I am / I'm** و**Nice to meet you**.", en: "Say hello, give your name and job, and answer someone who welcomes you. Focus on **I am / I'm** and **Nice to meet you**." },
    d: [["Omar", "Good morning! Are you the new developer?", "صباح الخير! إنت المبرمج الجديد؟"],
        ["Lina", "Yes, I am. I'm Lina. Today is my first day.", "أيوه. أنا لينا. النهارده أول يوم ليّا."],
        ["Omar", "Welcome to the team, Lina. I'm Omar, the team lead.", "أهلًا بيكي في الفريق يا لينا. أنا عمر، قائد الفريق."],
        ["Lina", "Nice to meet you, Omar.", "اتشرفت بيك يا عمر."],
        ["Omar", "Nice to meet you too. Your desk is next to the window.", "وأنا كمان. مكتبك جنب الشباك."],
        ["Lina", "Great, thank you. Where is the kitchen?", "تمام، شكرًا. المطبخ فين؟"],
        ["Omar", "It's at the end of the hall. Let's get a coffee.", "في آخر الطرقة. يلا نشرب قهوة."]],
    ph: [["Good morning!", "صباح الخير!"], ["I'm the new developer.", "أنا المبرمج الجديد."], ["Nice to meet you.", "اتشرفت بيك."], ["Welcome to the team.", "أهلًا بيك في الفريق."]],
    q: [["f", "Yes, I ___. I'm Lina.", "am", ["is", "are"], "مع I بنستخدم am دايمًا.", "With I we always use am."],
        ["f", "Nice to ___ you.", "meet", ["meat", "met"], "Nice to meet you = اتشرفت بمعرفتك. meat يعني لحمة.", "Nice to meet you is the fixed phrase. «meat» is food."],
        ["f", "___ to the team!", "Welcome", ["Welcomes", "Welcoming"], "Welcome to … جملة ترحيب ثابتة.", "«Welcome to …» is the fixed greeting."],
        ["m", "ترد بإيه لما حد يقولك Nice to meet you؟", "What do you answer to «Nice to meet you»?", ["Nice to meet you too.", "Yes, I meet.", "Good night."], 0, "بنرجّع نفس الجملة ونزود too.", "We return the same phrase and add «too»."],
        ["m", "مكتب لينا فين؟", "Where is Lina's desk?", ["Next to the window", "In the kitchen", "At the end of the hall"], 0, "عمر قال: Your desk is next to the window.", "Omar says: «Your desk is next to the window.»"]] },

  { id: "intro-online", t: { ar: "تعرّف نفسك في اجتماع أونلاين", en: "Introductions in an online team meeting" },
    body: { ar: "تقدّم نفسك في اجتماع فيديو: اسمك، ودورك، ومنين إنت، وبتشتغل على إيه. وتتعلم جمل الاجتماعات زي **Can you hear me?**", en: "Introduce yourself in a video meeting: your name, your role, where you are from and what you work on. Plus meeting phrases like **Can you hear me?**" },
    d: [["Sara", "Hi everyone. We have a new member today. Karim, can you introduce yourself?", "أهلًا يا جماعة. عندنا عضو جديد النهارده. كريم، تقدر تعرّفنا بنفسك؟"],
        ["Karim", "Sure. Can you hear me?", "أكيد. سامعيني؟"],
        ["Sara", "Yes, we can hear you.", "أيوه، سامعينك."],
        ["Karim", "Great. I'm Karim. I'm a mobile developer, and I'm from Alexandria.", "تمام. أنا كريم. مبرمج تطبيقات موبايل، ومن إسكندرية."],
        ["Karim", "I work on the Android app. I'm happy to be here.", "بشتغل على تطبيق الأندرويد. مبسوط إني معاكم."],
        ["Sara", "Thanks, Karim. Your camera is off, by the way.", "شكرًا يا كريم. على فكرة الكاميرا مقفولة."],
        ["Karim", "Oh, sorry! Is it on now?", "آه، آسف! كده اشتغلت؟"]],
    ph: [["Can you hear me?", "سامعيني؟"], ["I'm a mobile developer.", "أنا مبرمج موبايل."], ["I work on the Android app.", "بشتغل على تطبيق الأندرويد."], ["You're on mute.", "المايك عندك مقفول."]],
    q: [["f", "I'm ___ Alexandria.", "from", ["of", "at"], "بنقول I'm from + المدينة أو البلد.", "We say «I'm from» + city or country."],
        ["f", "I ___ on the Android app.", "work", ["works", "working"], "مع I الفعل في المضارع البسيط من غير s.", "With I the present simple verb has no -s."],
        ["f", "Can you ___ me?", "hear", ["here", "listen"], "hear = تسمع. here = هنا. listen محتاجة to.", "«hear» means receive sound; «here» is a place; «listen» needs «to»."],
        ["m", "تقول إيه لزميل صوته مش واصل لأن المايك مقفول؟", "What do you tell a colleague whose mic is off?", ["You're on mute.", "You're on camera.", "You're on time."], 0, "on mute = المايك مقفول.", "«on mute» means the microphone is off."],
        ["m", "كريم بيشتغل إيه؟", "What is Karim's job?", ["Mobile developer", "Team lead", "Designer"], 0, "قال: I'm a mobile developer.", "He says «I'm a mobile developer.»"]] },

  { id: "break-room", t: { ar: "تفتح كلام في الاستراحة", en: "Conversation starters in the break room" },
    body: { ar: "Small talk: كلام خفيف عن الويك إند والجو والقهوة. أسئلة زي **How was your weekend?** و**Did you …?**", en: "Small talk: light chat about the weekend, the weather and coffee. Questions like **How was your weekend?** and **Did you …?**" },
    d: [["Mona", "Hi Adam. How was your weekend?", "أهلًا يا آدم. الويك إند كان عامل إيه؟"],
        ["Adam", "It was nice, thanks. I visited my parents. How about you?", "كان حلو، شكرًا. زرت أهلي. وإنتي؟"],
        ["Mona", "Quiet. I watched a movie and read a little.", "هادي. اتفرجت على فيلم وقريت شوية."],
        ["Adam", "Do you want some coffee? The machine works again.", "تشربي قهوة؟ المكنة اشتغلت تاني."],
        ["Mona", "Yes, please. With milk, no sugar.", "أيوه لو سمحت. بلبن، من غير سكر."],
        ["Adam", "It's really hot today, right?", "الجو حر أوي النهارده، صح؟"],
        ["Mona", "Yes! I'm happy the office has air conditioning.", "أيوه! الحمد لله المكتب فيه تكييف."]],
    ph: [["How was your weekend?", "الويك إند كان عامل إيه؟"], ["How about you?", "وإنت؟"], ["Do you want some coffee?", "تشرب قهوة؟"], ["It's really hot today, right?", "الجو حر أوي النهارده، صح؟"]],
    q: [["f", "How ___ your weekend?", "was", ["is", "were"], "الويك إند خلص، فبنستخدم الماضي was.", "The weekend is over, so we use the past «was»."],
        ["f", "I ___ my parents.", "visited", ["visit", "visiting"], "حاجة خلصت في الماضي: الفعل + ed.", "A finished past action: verb + -ed."],
        ["f", "With milk, ___ sugar.", "no", ["not", "none"], "no + اسم = من غير. not بتيجي مع الأفعال.", "«no» + noun = without it; «not» goes with verbs."],
        ["m", "أنهي سؤال مناسب كبداية كلام خفيف؟", "Which question is a good small-talk opener?", ["How was your weekend?", "What is your salary?", "Why are you late?"], 0, "سؤال الويك إند لطيف ومش شخصي.", "The weekend question is friendly and not personal."],
        ["m", "Mona بتشرب القهوة إزاي؟", "How does Mona take her coffee?", ["With milk, no sugar", "Black with sugar", "She doesn't drink coffee"], 0, "قالت: With milk, no sugar.", "She says «With milk, no sugar.»"]] },

  { id: "workday", t: { ar: "توصف يوم شغلك ومهامك", en: "Talking about a typical workday and tasks" },
    body: { ar: "المضارع البسيط للعادة: **I usually…**، **every morning**، **after lunch**. وكلمات التكرار always / usually / sometimes / never.", en: "The present simple for routines: **I usually…**, **every morning**, **after lunch**. Plus frequency words always / usually / sometimes / never." },
    d: [["Tom", "Sofia, what does a normal day look like for you?", "صوفيا، يومك العادي شكله إيه؟"],
        ["Sofia", "I usually start at nine. First, I check my email and messages.", "عادةً ببدأ الساعة تسعة. الأول ببص على الإيميل والرسايل."],
        ["Sofia", "At ten we have the stand-up meeting.", "الساعة عشرة عندنا اجتماع الـ stand-up."],
        ["Tom", "And after that?", "وبعدها؟"],
        ["Sofia", "I write code until lunch. After lunch I review pull requests.", "بكتب كود لحد الغدا. بعد الغدا براجع الـ pull requests."],
        ["Tom", "Do you ever work late?", "بتتأخر في الشغل أحيانًا؟"],
        ["Sofia", "Sometimes, before a release. But I never work on Fridays.", "أحيانًا، قبل الإصدار. بس عمري ما بشتغل يوم الجمعة."]],
    ph: [["I usually start at nine.", "عادةً ببدأ الساعة تسعة."], ["First, I check my email.", "الأول ببص على الإيميل."], ["After lunch I review pull requests.", "بعد الغدا براجع الـ pull requests."], ["I never work on Fridays.", "عمري ما بشتغل يوم الجمعة."]],
    q: [["f", "She usually ___ at nine.", "starts", ["start", "starting"], "مع she/he/it بنزود s في المضارع البسيط.", "With he/she/it the present simple adds -s."],
        ["f", "I write code ___ lunch.", "until", ["since", "during"], "until = لحد.", "«until» means up to that time."],
        ["f", "What ___ a normal day look like?", "does", ["do", "is"], "سؤال عن it (a normal day) في المضارع: does.", "A question about «a normal day» (it) uses «does»."],
        ["m", "أنهي كلمة معناها «عمري ما»؟", "Which word means «not at any time»?", ["never", "usually", "sometimes"], 0, "never = أبدًا.", "«never» = at no time."],
        ["m", "صوفيا بتعمل إيه بعد الغدا؟", "What does Sofia do after lunch?", ["She reviews pull requests.", "She has the stand-up.", "She checks email."], 0, "After lunch I review pull requests.", "«After lunch I review pull requests.»"]] },

  { id: "routine", t: { ar: "روتينك الصبح وبالليل", en: "Your morning and evening routine" },
    body: { ar: "تحكي روتينك بالترتيب: **first, then, after that, finally**، والوقت **at 7, in the morning, at night**.", en: "Tell your routine in order: **first, then, after that, finally**, and times **at 7, in the morning, at night**." },
    d: [["Nour", "What time do you get up, Ali?", "بتصحى الساعة كام يا علي؟"],
        ["Ali", "At seven. Then I have breakfast and take the metro.", "الساعة سبعة. بعدين بفطر وباخد المترو."],
        ["Nour", "Do you read on the metro?", "بتقرا في المترو؟"],
        ["Ali", "Yes, I read tech articles on my phone.", "أيوه، بقرا مقالات تقنية على الموبايل."],
        ["Nour", "And in the evening?", "وبالليل؟"],
        ["Ali", "I go to the gym, I cook dinner, and finally I study English for thirty minutes.", "بروح الجيم، وبطبخ العشا، وفي الآخر بذاكر إنجليزي نص ساعة."],
        ["Nour", "That's a good routine!", "ده روتين حلو!"]],
    ph: [["What time do you get up?", "بتصحى الساعة كام؟"], ["Then I have breakfast.", "بعدين بفطر."], ["In the evening I go to the gym.", "بالليل بروح الجيم."], ["Finally, I study for thirty minutes.", "وفي الآخر بذاكر نص ساعة."]],
    q: [["f", "I get up ___ seven.", "at", ["in", "on"], "at مع الساعة بالظبط.", "«at» goes with clock times."],
        ["f", "I go to the gym ___ the evening.", "in", ["at", "on"], "in the morning / in the evening، بس at night.", "«in the morning / in the evening», but «at night»."],
        ["f", "What time ___ you get up?", "do", ["does", "are"], "سؤال مع you في المضارع البسيط: do.", "A present-simple question with «you» uses «do»."],
        ["m", "أنهي كلمة بتقولها لآخر خطوة؟", "Which word introduces the last step?", ["Finally", "First", "Then"], 0, "Finally = وفي الآخر.", "«Finally» introduces the last step."],
        ["m", "علي بيعمل إيه في المترو؟", "What does Ali do on the metro?", ["He reads tech articles.", "He sleeps.", "He writes code."], 0, "I read tech articles on my phone.", "«I read tech articles on my phone.»"]] },

  { id: "project", t: { ar: "توصف المشروع اللي شغال عليه", en: "Describing your current project" },
    body: { ar: "المضارع المستمر للي بيحصل دلوقتي: **I'm working on…**، **We're building…**، وتوصف الهدف والأدوات.", en: "The present continuous for what is happening now: **I'm working on…**, **We're building…**, and describe the goal and the tools." },
    d: [["James", "What are you working on these days, Sophie?", "شغالة على إيه اليومين دول يا صوفي؟"],
        ["Sophie", "I'm working on a booking app for a clinic.", "شغالة على تطبيق حجز لعيادة."],
        ["James", "Interesting. What does it do?", "حلو. بيعمل إيه؟"],
        ["Sophie", "Patients choose a time and get a reminder by SMS.", "المرضى بيختاروا معاد وبيوصلهم تذكير بالـ SMS."],
        ["James", "Which tools are you using?", "بتستخدمي أدوات إيه؟"],
        ["Sophie", "React for the front end and Python for the API. And you?", "React للواجهة وPython للـ API. وإنت؟"],
        ["James", "We're building a dashboard for the sales team.", "إحنا بنبني dashboard لفريق المبيعات."]],
    ph: [["I'm working on a booking app.", "أنا شغال على تطبيق حجز."], ["What does it do?", "بيعمل إيه؟"], ["Which tools are you using?", "بتستخدم أدوات إيه؟"], ["We're building a dashboard.", "إحنا بنبني dashboard."]],
    q: [["f", "I'm ___ on a booking app.", "working", ["work", "worked"], "am/is/are + فعل بـ ing للي بيحصل دلوقتي.", "am/is/are + -ing for what is happening now."],
        ["f", "We ___ building a dashboard.", "are", ["is", "am"], "مع we بنستخدم are.", "With «we» we use «are»."],
        ["f", "Which tools ___ you using?", "are", ["do", "is"], "سؤال في المضارع المستمر: are + you + ing.", "A present-continuous question: are + you + -ing."],
        ["m", "التطبيق بيبعت إيه للمرضى؟", "What does the app send to patients?", ["A reminder by SMS", "An invoice by email", "A video"], 0, "get a reminder by SMS.", "«get a reminder by SMS»."],
        ["m", "أنهي جملة بتوصف مشروع بيحصل دلوقتي؟", "Which sentence describes a project in progress?", ["I'm working on a new API.", "I work on a new API yesterday.", "I working on a new API."], 0, "am + working صح. التانيين فيهم غلطة.", "«am + working» is right; the others have a mistake."]] },

  { id: "background", t: { ar: "تسأل وتحكي عن دراستك وخبرتك", en: "Educational and professional background" },
    body: { ar: "في مقابلة شغل: **I studied…**، **I graduated in…**، **I have worked as… for two years**.", en: "In a job interview: **I studied…**, **I graduated in…**, **I have worked as… for two years**." },
    d: [["Interviewer", "Tell me about your education.", "احكيلي عن دراستك."],
        ["Hana", "I studied computer science at Cairo University. I graduated in 2022.", "درست علوم حاسب في جامعة القاهرة. اتخرجت سنة 2022."],
        ["Interviewer", "And your work experience?", "وخبرتك في الشغل؟"],
        ["Hana", "I have worked as a junior web developer for two years.", "بشتغل مبرمجة ويب جونيور بقالي سنتين."],
        ["Interviewer", "What did you learn in that job?", "اتعلمتي إيه في الشغلانة دي؟"],
        ["Hana", "I learned to work with Git and to write tests.", "اتعلمت أشتغل بـ Git وأكتب اختبارات."],
        ["Interviewer", "Good. Did you take any online courses?", "كويس. أخدتي كورسات أونلاين؟"],
        ["Hana", "Yes, I finished a course in cloud basics last year.", "أيوه، خلصت كورس أساسيات الكلاود السنة اللي فاتت."]],
    ph: [["I studied computer science.", "درست علوم حاسب."], ["I graduated in 2022.", "اتخرجت سنة 2022."], ["I have worked as a web developer for two years.", "بشتغل مبرمج ويب بقالي سنتين."], ["I finished a course last year.", "خلصت كورس السنة اللي فاتت."]],
    q: [["f", "I graduated ___ 2022.", "in", ["on", "at"], "in مع السنين والشهور.", "«in» goes with years and months."],
        ["f", "I have worked here ___ two years.", "for", ["since", "from"], "for + مدة (two years). since + بداية (2022).", "«for» + a period; «since» + a starting point."],
        ["f", "I ___ computer science at university.", "studied", ["study", "studying"], "حاجة خلصت في الماضي: studied.", "Finished past: «studied»."],
        ["m", "أنهي جملة صح؟", "Which sentence is correct?", ["I have worked here since 2022.", "I have worked here for 2022.", "I work here since 2022."], 0, "since + سنة البداية، ومعاها have worked.", "«since» + the start year, with «have worked»."],
        ["m", "هنا اتعلمت إيه في شغلها؟", "What did Hana learn in her job?", ["Git and writing tests", "Cloud basics", "Design"], 0, "I learned to work with Git and to write tests.", "«I learned to work with Git and to write tests.»"]] },

  { id: "hobbies", t: { ar: "الهوايات والاهتمامات", en: "Hobbies and interests" },
    body: { ar: "**I like / I love / I enjoy + ing**، و**I'm interested in…**، و**How often…?**", en: "**I like / I love / I enjoy + -ing**, **I'm interested in…**, and **How often…?**" },
    d: [["Yara", "What do you do in your free time, Sam?", "بتعمل إيه في وقت فراغك يا سام؟"],
        ["Sam", "I love taking photos. I'm interested in street photography.", "بحب أصوّر. مهتم بتصوير الشوارع."],
        ["Yara", "Cool! How often do you go out to take photos?", "حلو! بتنزل تصوّر كل قد إيه؟"],
        ["Sam", "Every Saturday morning. What about you?", "كل سبت الصبح. وإنتي؟"],
        ["Yara", "I enjoy playing chess online, and I like hiking.", "بحب ألعب شطرنج أونلاين، وبحب المشي في الجبال."],
        ["Sam", "Do you play with people from work?", "بتلعبي مع ناس من الشغل؟"],
        ["Yara", "Yes, with two people from the QA team.", "أيوه، مع اتنين من فريق الـ QA."]],
    ph: [["What do you do in your free time?", "بتعمل إيه في وقت فراغك؟"], ["I love taking photos.", "بحب أصوّر."], ["I'm interested in photography.", "مهتم بالتصوير."], ["How often do you…?", "بتعمل … كل قد إيه؟"]],
    q: [["f", "I enjoy ___ chess.", "playing", ["play", "to playing"], "enjoy بعدها فعل بـ ing.", "«enjoy» is followed by -ing."],
        ["f", "I'm interested ___ photography.", "in", ["on", "about"], "interested in تركيبة ثابتة.", "«interested in» is fixed."],
        ["f", "How ___ do you go hiking?", "often", ["much", "many"], "How often = كل قد إيه.", "«How often» asks about frequency."],
        ["m", "أنهي سؤال بيسأل عن الهوايات؟", "Which question asks about hobbies?", ["What do you do in your free time?", "What time is it?", "Where is the office?"], 0, "free time = وقت الفراغ.", "«free time» is time away from work."],
        ["m", "سام بيصوّر إمتى؟", "When does Sam take photos?", ["Every Saturday morning", "Every evening", "On Fridays"], 0, "Every Saturday morning.", "«Every Saturday morning.»"]] },

  { id: "roles", t: { ar: "الأدوار والمسؤوليات", en: "Roles and responsibilities" },
    body: { ar: "توصف مين بيعمل إيه: **She is in charge of…**، **He is responsible for…**، **They take care of…**.", en: "Describe who does what: **She is in charge of…**, **He is responsible for…**, **They take care of…**." },
    d: [["Leo", "I'm still learning who does what. Who is Dina?", "لسه بتعلم مين بيعمل إيه. مين دينا؟"],
        ["Rana", "Dina is our product manager. She is in charge of the roadmap.", "دينا مديرة المنتج. هي المسؤولة عن خطة المنتج."],
        ["Leo", "And Hassan?", "وحسن؟"],
        ["Rana", "He's the DevOps engineer. He is responsible for the servers and deployments.", "مهندس DevOps. مسؤول عن السيرفرات والنشر."],
        ["Leo", "Who tests the features?", "مين بيختبر الخواص الجديدة؟"],
        ["Rana", "The QA team. They write test plans and report bugs.", "فريق الـ QA. بيكتبوا خطط الاختبار وبيبلّغوا عن الـ bugs."],
        ["Leo", "Thanks, that helps a lot.", "شكرًا، ده ساعدني كتير."]],
    ph: [["She is in charge of the roadmap.", "هي المسؤولة عن خطة المنتج."], ["He is responsible for the servers.", "هو مسؤول عن السيرفرات."], ["They report bugs.", "بيبلّغوا عن الـ bugs."], ["Who does what?", "مين بيعمل إيه؟"]],
    q: [["f", "He is responsible ___ the servers.", "for", ["of", "to"], "responsible for تركيبة ثابتة.", "«responsible for» is fixed."],
        ["f", "She is in charge ___ the roadmap.", "of", ["for", "with"], "in charge of تركيبة ثابتة.", "«in charge of» is fixed."],
        ["f", "The QA team ___ bugs.", "reports", ["report", "reporting"], "The team (مفرد) → reports. ولو قلت They يبقى report.", "«The team» is singular here → «reports»."],
        ["m", "مين مسؤول عن النشر (deployments)؟", "Who is responsible for deployments?", ["Hassan", "Dina", "The QA team"], 0, "Hassan is the DevOps engineer.", "Hassan, the DevOps engineer."],
        ["m", "product manager بيعمل إيه في الحوار؟", "What does the product manager do in the dialogue?", ["She is in charge of the roadmap.", "She tests features.", "She manages servers."], 0, "She is in charge of the roadmap.", "«She is in charge of the roadmap.»"]] },

  { id: "motivation", t: { ar: "التفضيلات والدوافع", en: "Preferences and motivations" },
    body: { ar: "**I prefer A to B**، **I'd rather…**، **What motivates you?**، و**because** عشان تدّي السبب.", en: "**I prefer A to B**, **I'd rather…**, **What motivates you?**, and **because** to give a reason." },
    d: [["Maya", "Do you prefer working from home or from the office?", "تحب تشتغل من البيت ولا من المكتب؟"],
        ["Ziad", "I prefer the office, because I can ask questions quickly.", "بفضّل المكتب، عشان أقدر أسأل بسرعة."],
        ["Maya", "I'd rather work from home. It's quieter.", "أنا أفضّل أشتغل من البيت. أهدى."],
        ["Ziad", "What motivates you in this job?", "إيه اللي بيحمّسك في الشغلانة دي؟"],
        ["Maya", "Solving hard problems. And you?", "حل المشاكل الصعبة. وإنت؟"],
        ["Ziad", "Learning new things. I get bored when I do the same task every day.", "إني أتعلم حاجات جديدة. بزهق لما أعمل نفس المهمة كل يوم."]],
    ph: [["I prefer the office to home.", "بفضّل المكتب عن البيت."], ["I'd rather work from home.", "أفضّل أشتغل من البيت."], ["What motivates you?", "إيه اللي بيحمّسك؟"], ["I get bored when…", "بزهق لما…"]],
    q: [["f", "I prefer tea ___ coffee.", "to", ["than", "from"], "prefer A to B. (than بتيجي مع rather).", "«prefer A to B» («than» goes with «rather»)."],
        ["f", "I'd rather ___ from home.", "work", ["working", "to work"], "would rather + فعل من غير to.", "«would rather» + bare verb."],
        ["f", "I prefer the office, ___ I can ask questions quickly.", "because", ["so", "but"], "because بتقول السبب.", "«because» gives the reason."],
        ["m", "إيه اللي بيحمّس زياد؟", "What motivates Ziad?", ["Learning new things", "Working from home", "Doing the same task"], 0, "Learning new things.", "«Learning new things.»"],
        ["m", "أنهي جملة صح؟", "Which sentence is correct?", ["I'd rather stay at home.", "I'd rather to stay at home.", "I'd rather staying at home."], 0, "would rather + stay.", "«would rather» + bare verb."]] },

  { id: "trends", t: { ar: "تتكلم عن ترندات التكنولوجيا", en: "Popular trends in technology" },
    body: { ar: "تقول رأيك ببساطة: **I think…**، **In my opinion…**، **It's useful for…**، **I'm not sure about…**.", en: "Give a simple opinion: **I think…**, **In my opinion…**, **It's useful for…**, **I'm not sure about…**." },
    d: [["Ahmed", "Everyone is talking about AI assistants. What do you think?", "الكل بيتكلم عن مساعدين الذكاء الاصطناعي. رأيك إيه؟"],
        ["Julia", "I think they are useful for simple code and for tests.", "أعتقد إنهم مفيدين للكود البسيط وللاختبارات."],
        ["Ahmed", "Do you use one at work?", "بتستخدمي واحد في الشغل؟"],
        ["Julia", "Yes, every day. But I always check the code it writes.", "أيوه، كل يوم. بس دايمًا براجع الكود اللي بيكتبه."],
        ["Ahmed", "In my opinion, they make some people lazy.", "في رأيي، بيخلّوا ناس تكسل."],
        ["Julia", "Maybe. I'm not sure about that. It depends on the person.", "ممكن. مش متأكدة من ده. على حسب الشخص."]],
    ph: [["What do you think?", "رأيك إيه؟"], ["I think they are useful for tests.", "أعتقد إنهم مفيدين للاختبارات."], ["In my opinion, …", "في رأيي، …"], ["It depends on the person.", "على حسب الشخص."]],
    q: [["f", "They are useful ___ simple code.", "for", ["to", "at"], "useful for + اسم.", "«useful for» + noun."],
        ["f", "It depends ___ the person.", "on", ["of", "from"], "depends on تركيبة ثابتة.", "«depends on» is fixed."],
        ["f", "In my ___, they make people lazy.", "opinion", ["think", "idea"], "In my opinion تركيبة ثابتة.", "«In my opinion» is fixed."],
        ["m", "جوليا بتعمل إيه مع الكود اللي بيكتبه المساعد؟", "What does Julia do with the code the assistant writes?", ["She always checks it.", "She never uses it.", "She sends it to Ahmed."], 0, "I always check the code it writes.", "«I always check the code it writes.»"],
        ["m", "أنهي جملة تقول بيها إنك مش متأكد؟", "Which sentence says you are not sure?", ["I'm not sure about that.", "I'm sure about that.", "That's right."], 0, "not sure = مش متأكد.", "«not sure» = uncertain."]] },

  { id: "clarify", t: { ar: "توضّح المعلومة في مواقف مختلفة", en: "Clarifying information" },
    body: { ar: "لما ماتفهمش: **Sorry, could you repeat that?**، **Do you mean…?**، **How do you spell that?**", en: "When you don't understand: **Sorry, could you repeat that?**, **Do you mean…?**, **How do you spell that?**" },
    d: [["Manager", "Please send the report to Mr. Kowalski before Thursday.", "ابعت التقرير لأستاذ كوالسكي قبل الخميس."],
        ["Reem", "Sorry, could you repeat the name?", "آسفة، ممكن تعيد الاسم؟"],
        ["Manager", "Kowalski. He's the new client.", "كوالسكي. ده العميل الجديد."],
        ["Reem", "How do you spell that?", "بيتكتب إزاي؟"],
        ["Manager", "K-O-W-A-L-S-K-I.", "K-O-W-A-L-S-K-I."],
        ["Reem", "Thanks. Do you mean this Thursday or next Thursday?", "شكرًا. تقصد الخميس ده ولا الخميس الجاي؟"],
        ["Manager", "This Thursday, please.", "الخميس ده لو سمحت."]],
    ph: [["Sorry, could you repeat that?", "آسف، ممكن تعيد؟"], ["How do you spell that?", "بيتكتب إزاي؟"], ["Do you mean this Thursday?", "تقصد الخميس ده؟"], ["Could you speak more slowly?", "ممكن تتكلم أبطأ؟"]],
    q: [["f", "Could you ___ that, please?", "repeat", ["repeating", "repeats"], "could + فعل من غير إضافات.", "«could» + bare verb."],
        ["f", "How do you ___ that?", "spell", ["write it", "say"], "How do you spell…? = بيتكتب إزاي حرف حرف.", "«How do you spell…?» asks for the letters."],
        ["f", "Do you ___ this Thursday?", "mean", ["say", "think"], "Do you mean…? = تقصد…؟", "«Do you mean…?» checks meaning."],
        ["m", "التقرير لازم يتبعت إمتى؟", "When must the report be sent?", ["Before this Thursday", "Next Thursday", "Today"], 0, "This Thursday, please.", "«This Thursday, please.»"],
        ["m", "تقول إيه لو حد بيتكلم بسرعة؟", "What do you say if someone speaks too fast?", ["Could you speak more slowly?", "Could you speak more fast?", "Speak!"], 0, "more slowly = أبطأ.", "«more slowly» is the polite request."]] },

  { id: "prog-vocab", t: { ar: "مفردات البرمجة الأساسية في الكلام", en: "Basic programming vocabulary in conversation" },
    body: { ar: "كلمات زي variable وfunction وloop وbug وrun بتتقال إزاي في جملة. **The function returns…**، **The loop runs…**.", en: "How words like variable, function, loop, bug and run sit in a sentence. **The function returns…**, **The loop runs…**." },
    d: [["Mentor", "What does this function do?", "الـ function دي بتعمل إيه؟"],
        ["Intern", "It takes a list of prices and returns the total.", "بتاخد ليستة أسعار وبترجّع المجموع."],
        ["Mentor", "Good. And this loop?", "كويس. والـ loop ده؟"],
        ["Intern", "It goes through every price and adds it to the variable total.", "بيلف على كل سعر ويزوّده على الـ variable اللي اسمه total."],
        ["Mentor", "When you run it, what happens?", "لما تشغّله، بيحصل إيه؟"],
        ["Intern", "It prints zero. I think there's a bug.", "بيطبع صفر. أعتقد فيه bug."],
        ["Mentor", "Look at where you return. It's inside the loop.", "بص إنت بترجّع فين. جوه الـ loop."]],
    ph: [["It returns the total.", "بترجّع المجموع."], ["The loop goes through every item.", "الـ loop بيلف على كل عنصر."], ["When I run it, it prints zero.", "لما بشغّله بيطبع صفر."], ["I think there's a bug.", "أعتقد فيه bug."]],
    q: [["f", "The function ___ the total.", "returns", ["return", "returning"], "The function (مفرد) → returns.", "«The function» is singular → «returns»."],
        ["f", "The loop goes ___ every price.", "through", ["across", "over to"], "go through = يعدّي على كل واحد.", "«go through» = visit each one."],
        ["f", "I think ___ a bug.", "there's", ["it's have", "there are"], "there's + مفرد = فيه.", "«there's» + singular = it exists."],
        ["m", "إيه سبب الـ bug في الحوار؟", "What causes the bug in the dialogue?", ["The return is inside the loop.", "The variable has no name.", "The list is empty."], 0, "It's inside the loop.", "The return is inside the loop."],
        ["m", "كلمة run هنا معناها إيه؟", "What does «run» mean here?", ["Start the program", "Move fast", "Delete the code"], 0, "run the code = تشغّله.", "To run code is to execute it."]] },

  { id: "code-terms", t: { ar: "مفاهيم ومصطلحات الكود", en: "Code-related concepts and terms" },
    body: { ar: "أنواع البيانات: string وnumber وboolean وarray وobject، وإزاي تسأل عنهم: **What type is…?**، **Is it a string or a number?**", en: "Data types: string, number, boolean, array and object, and how to ask about them: **What type is…?**, **Is it a string or a number?**" },
    d: [["Bella", "What type is the user ID? Is it a string or a number?", "الـ user ID نوعه إيه؟ string ولا number؟"],
        ["Hadi", "It's a string. Some IDs start with letters.", "string. فيه IDs بتبدأ بحروف."],
        ["Bella", "And isActive?", "و isActive؟"],
        ["Hadi", "That's a boolean, true or false.", "ده boolean، true أو false."],
        ["Bella", "The API returns a list of users. Is that an array?", "الـ API بيرجّع ليستة users. ده array؟"],
        ["Hadi", "Yes, an array of objects. Each object has a name and an email.", "أيوه، array من الـ objects. كل object فيه name وemail."]],
    ph: [["What type is it?", "نوعه إيه؟"], ["It's a string.", "ده string."], ["That's a boolean, true or false.", "ده boolean، true أو false."], ["An array of objects", "array من الـ objects"]],
    q: [["f", "Is it a string ___ a number?", "or", ["and", "but"], "or في السؤال للاختيار بين حاجتين.", "«or» offers a choice in a question."],
        ["f", "Each object ___ a name and an email.", "has", ["have", "having"], "Each + مفرد → has.", "«Each» takes a singular verb → «has»."],
        ["f", "That's ___ boolean.", "a", ["an", "the"], "a قبل صوت ساكن (b).", "«a» before a consonant sound."],
        ["m", "isActive نوعه إيه؟", "What type is isActive?", ["boolean", "string", "array"], 0, "true or false = boolean.", "true or false = boolean."],
        ["m", "ليه الـ user ID string مش number؟", "Why is the user ID a string?", ["Some IDs start with letters.", "It is very long.", "It is secret."], 0, "Some IDs start with letters.", "«Some IDs start with letters.»"]] },

  { id: "tech-updates", t: { ar: "تحديثات وأخبار التقنية", en: "Tech updates and new ideas" },
    body: { ar: "تحكي خبر وتقترح فكرة: **Did you hear about…?**، **We could try…**، **What if we…?**", en: "Share news and suggest an idea: **Did you hear about…?**, **We could try…**, **What if we…?**" },
    d: [["Eva", "Did you hear about the new low-code tool from our cloud provider?", "سمعت عن أداة الـ low-code الجديدة من شركة الكلاود بتاعتنا؟"],
        ["Malik", "Yes, I read the announcement. It looks easy to use.", "أيوه، قريت الإعلان. شكلها سهلة."],
        ["Eva", "We could try it for the internal forms.", "ممكن نجرّبها للفورمات الداخلية."],
        ["Malik", "Good idea. What if we build one small form first?", "فكرة حلوة. إيه رأيك نبني فورم صغيرة الأول؟"],
        ["Eva", "Sure. Let's show it to the team on Monday.", "أكيد. نعرضها على الفريق يوم الاتنين."]],
    ph: [["Did you hear about…?", "سمعت عن…؟"], ["It looks easy to use.", "شكلها سهلة."], ["We could try it.", "ممكن نجرّبها."], ["What if we build one small form first?", "إيه رأيك نبني فورم صغيرة الأول؟"]],
    q: [["f", "Did you ___ about the new tool?", "hear", ["heard", "hearing"], "بعد did الفعل يرجع لأصله.", "After «did» the verb is in its base form."],
        ["f", "We ___ try it for the forms.", "could", ["can to", "should to"], "could + فعل = اقتراح لطيف.", "«could» + verb is a soft suggestion."],
        ["f", "What if we ___ one small form first?", "build", ["builds", "building"], "What if we + فعل.", "«What if we» + base verb."],
        ["m", "هيعرضوا الفكرة على الفريق إمتى؟", "When will they show it to the team?", ["On Monday", "Today", "Next month"], 0, "Let's show it to the team on Monday.", "«…on Monday.»"],
        ["m", "أنهي جملة اقتراح؟", "Which sentence is a suggestion?", ["We could try it.", "We tried it.", "We are trying it."], 0, "could = اقتراح.", "«could» suggests."]] },

  { id: "github-help", t: { ar: "تساعد زميل يحل مشكلة على GitHub", en: "Helping a coworker troubleshoot on GitHub" },
    body: { ar: "كلمات GitHub في الكلام: issue وbranch وcommit وpull request وmerge conflict. **Did you pull the latest changes?**", en: "GitHub words in speech: issue, branch, commit, pull request, merge conflict. **Did you pull the latest changes?**" },
    d: [["Fady", "I can't merge my pull request. GitHub says there's a conflict.", "مش قادر أعمل merge للـ pull request. GitHub بيقول فيه conflict."],
        ["Lea", "Did you pull the latest changes from main?", "عملت pull لآخر التغييرات من main؟"],
        ["Fady", "No, I didn't.", "لأ، ماعملتش."],
        ["Lea", "Pull them first. Then open the file with the conflict and choose the right lines.", "اعملهم pull الأول. بعدين افتح الملف اللي فيه الـ conflict واختار السطور الصح."],
        ["Fady", "OK, done. Now I commit and push again?", "تمام، خلصت. أعمل commit وpush تاني؟"],
        ["Lea", "Yes. And link the issue number in the description.", "أيوه. واربط رقم الـ issue في الوصف."]],
    ph: [["There's a merge conflict.", "فيه merge conflict."], ["Did you pull the latest changes?", "عملت pull لآخر التغييرات؟"], ["Commit and push again.", "اعمل commit وpush تاني."], ["Link the issue in the description.", "اربط الـ issue في الوصف."]],
    q: [["f", "Did you ___ the latest changes?", "pull", ["pulled", "pulling"], "بعد did الفعل في أصله.", "After «did», base form."],
        ["f", "No, I ___.", "didn't", ["don't", "wasn't"], "الرد القصير على سؤال بـ Did: No, I didn't.", "Short answer to a «Did» question: «No, I didn't.»"],
        ["f", "Pull them ___. Then fix the file.", "first", ["firstly then", "one"], "first = الأول.", "«first» = before anything else."],
        ["m", "إيه أول حاجة لازم فادي يعملها؟", "What must Fady do first?", ["Pull the latest changes from main", "Delete the branch", "Close the issue"], 0, "Pull them first.", "«Pull them first.»"],
        ["m", "merge conflict معناها إيه؟", "What is a merge conflict?", ["Two changes touch the same lines", "The server is down", "A missing password"], 0, "تغييرين في نفس السطور ولازم تختار.", "Two changes edit the same lines and you must choose."]] },

  { id: "standup", t: { ar: "تشارك تقدّمك في الـ stand-up", en: "Sharing your progress in the stand-up" },
    body: { ar: "التلات أسئلة: عملت إيه امبارح، هتعمل إيه النهارده، وفيه حاجة موقفاك؟ **Yesterday I…, Today I'll…, I'm blocked by…**", en: "The three questions: what you did yesterday, what you'll do today, and any blockers. **Yesterday I…, Today I'll…, I'm blocked by…**" },
    d: [["Lead", "Let's start. Nada, you first.", "يلا نبدأ. ندى، إنتي الأول."],
        ["Nada", "Yesterday I finished the login page.", "امبارح خلصت صفحة الدخول."],
        ["Nada", "Today I'll start the password reset email.", "النهارده هبدأ إيميل استرجاع الباسورد."],
        ["Nada", "I'm blocked by the email service. I don't have the API key yet.", "واقفة بسبب خدمة الإيميل. لسه ماعنديش الـ API key."],
        ["Lead", "I'll ask Hassan to send it after the meeting.", "هطلب من حسن يبعتهولك بعد الاجتماع."],
        ["Nada", "Thanks. That's all from me.", "شكرًا. ده كل اللي عندي."]],
    ph: [["Yesterday I finished…", "امبارح خلصت…"], ["Today I'll start…", "النهارده هبدأ…"], ["I'm blocked by…", "واقف بسبب…"], ["That's all from me.", "ده كل اللي عندي."]],
    q: [["f", "Yesterday I ___ the login page.", "finished", ["finish", "will finish"], "Yesterday = ماضي.", "«Yesterday» needs the past."],
        ["f", "Today I'___ start the reset email.", "ll", ["m", "d"], "I'll = I will للخطة.", "«I'll» = I will, for a plan."],
        ["f", "I'm blocked ___ the email service.", "by", ["from", "with"], "blocked by = واقف بسبب.", "«blocked by» names the cause."],
        ["m", "إيه اللي موقّف ندى؟", "What is blocking Nada?", ["She doesn't have the API key.", "Her laptop is broken.", "She is sick."], 0, "I don't have the API key yet.", "«I don't have the API key yet.»"],
        ["m", "تقول إيه لما تخلّص كلامك في الـ stand-up؟", "What do you say when you finish your update?", ["That's all from me.", "Goodbye forever.", "Start now."], 0, "That's all from me = ده كل اللي عندي.", "«That's all from me.»"]] },

  { id: "ask-code", t: { ar: "تطلب توضيح عشان تفهم كود", en: "Asking for clarification on code" },
    body: { ar: "**Could you walk me through…?**، **Why do we need…?**، **What happens if…?**", en: "**Could you walk me through…?**, **Why do we need…?**, **What happens if…?**" },
    d: [["Ines", "Hi Victor, do you have a minute? I don't understand this part of the code.", "أهلًا فيكتور، فاضي دقيقة؟ مش فاهمة الجزء ده من الكود."],
        ["Victor", "Sure. Which part?", "أكيد. أنهي جزء؟"],
        ["Ines", "This cache function. Why do we need it?", "الـ function بتاعة الـ cache. محتاجينها ليه؟"],
        ["Victor", "It saves the result, so we don't call the API every time.", "بتحفظ النتيجة، عشان مانكلمش الـ API كل مرة."],
        ["Ines", "What happens if the data changes?", "طب ولو البيانات اتغيرت؟"],
        ["Victor", "The cache expires after five minutes, and then we call the API again.", "الـ cache بيخلص بعد خمس دقايق، وبعدها بنكلّم الـ API تاني."],
        ["Ines", "Got it. Could you walk me through the tests too?", "فهمت. ممكن تشرحلي الاختبارات كمان خطوة بخطوة؟"]],
    ph: [["Do you have a minute?", "فاضي دقيقة؟"], ["Why do we need it?", "محتاجينها ليه؟"], ["What happens if…?", "إيه اللي بيحصل لو…؟"], ["Could you walk me through it?", "ممكن تشرحهولي خطوة بخطوة؟"]],
    q: [["f", "Do you have a ___?", "minute", ["minutes", "time to"], "Do you have a minute? جملة مؤدبة لطلب وقت.", "«Do you have a minute?» politely asks for time."],
        ["f", "What happens ___ the data changes?", "if", ["when it", "so"], "What happens if… = إيه اللي يحصل لو…", "«What happens if…» asks about a condition."],
        ["f", "Could you walk me ___ the tests?", "through", ["on", "in"], "walk someone through = تشرح خطوة بخطوة.", "«walk someone through» = explain step by step."],
        ["m", "الـ cache بيخلص بعد قد إيه؟", "When does the cache expire?", ["After five minutes", "Every day", "Never"], 0, "after five minutes.", "«after five minutes»."],
        ["m", "ليه محتاجين الـ cache؟", "Why do they need the cache?", ["So they don't call the API every time", "To delete old data", "To send emails"], 0, "so we don't call the API every time.", "«so we don't call the API every time.»"]] },

  { id: "doc-code", t: { ar: "توثّق الكود في مشروع", en: "Documenting code for a project" },
    body: { ar: "تكتب README وتعليقات: الأمر (imperative) في الخطوات **Install…, Run…**، و**This function…** في الوصف.", en: "Write a README and comments: the imperative for steps **Install…, Run…**, and **This function…** for descriptions." },
    d: [["Kim", "Our README is almost empty. Can you help me write it?", "الـ README بتاعنا شبه فاضي. تساعدني نكتبه؟"],
        ["Rami", "Sure. First, a short description: what the project does.", "أكيد. الأول وصف قصير: المشروع بيعمل إيه."],
        ["Kim", "Then the setup steps?", "بعدين خطوات التشغيل؟"],
        ["Rami", "Yes. Write them as commands: Install Node. Run npm install. Start the server.", "أيوه. اكتبها أوامر: Install Node. Run npm install. Start the server."],
        ["Kim", "Should I add comments in the code too?", "أضيف تعليقات في الكود كمان؟"],
        ["Rami", "Only where the code is not clear. Explain why, not what.", "بس في الأماكن اللي الكود مش واضح فيها. اشرح ليه، مش إيه."]],
    ph: [["A short description of what the project does", "وصف قصير المشروع بيعمل إيه"], ["Run npm install.", "شغّل npm install."], ["This function sends the invoice.", "الـ function دي بتبعت الفاتورة."], ["Explain why, not what.", "اشرح ليه، مش إيه."]],
    q: [["f", "___ npm install. (a README step)", "Run", ["Running", "To run"], "خطوات التوثيق بتتكتب بصيغة الأمر.", "Doc steps use the imperative."],
        ["f", "This function ___ the invoice.", "sends", ["send", "sending"], "This function (مفرد) → sends.", "«This function» → «sends»."],
        ["f", "Explain why, not ___.", "what", ["who", "where"], "التعليق الكويس بيشرح السبب، مش اللي الكود بيقوله.", "A good comment explains the reason, not the obvious."],
        ["m", "إيه أول حاجة في الـ README حسب رامي؟", "What comes first in the README, says Rami?", ["A short description", "The license", "The tests"], 0, "First, a short description.", "«First, a short description.»"],
        ["m", "إمتى نكتب تعليقات في الكود؟", "When should we add comments?", ["Where the code is not clear", "On every line", "Never"], 0, "Only where the code is not clear.", "«Only where the code is not clear.»"]] },

  { id: "read-docs", t: { ar: "تقرا التوثيق وتفهمه", en: "Reading and understanding documentation" },
    body: { ar: "كلمات التوثيق: parameter وrequired وoptional وdefault وexample وdeprecated. **According to the docs…**", en: "Docs words: parameter, required, optional, default, example, deprecated. **According to the docs…**" },
    d: [["Omar", "How do I set the timeout in this library?", "أظبط الـ timeout في المكتبة دي إزاي؟"],
        ["Lina", "According to the docs, it's an optional parameter.", "حسب التوثيق، ده parameter اختياري."],
        ["Omar", "What's the default value?", "القيمة الافتراضية كام؟"],
        ["Lina", "Thirty seconds. There's an example at the bottom of the page.", "تلاتين ثانية. فيه مثال تحت في الصفحة."],
        ["Omar", "And this old function?", "والـ function القديمة دي؟"],
        ["Lina", "It's deprecated. The docs say to use the new one instead.", "دي deprecated. التوثيق بيقول استخدم الجديدة بدالها."]],
    ph: [["According to the docs…", "حسب التوثيق…"], ["It's an optional parameter.", "ده parameter اختياري."], ["The default value is thirty seconds.", "القيمة الافتراضية تلاتين ثانية."], ["It's deprecated. Use the new one instead.", "دي قديمة وهتتشال. استخدم الجديدة بدالها."]],
    q: [["f", "___ to the docs, it's optional.", "According", ["Accord", "Based"], "According to = حسب.", "«According to» = as stated by."],
        ["f", "Use the new one ___.", "instead", ["instead of", "replace"], "instead في آخر الجملة = بدالها.", "«instead» at the end = in its place."],
        ["f", "The ___ value is thirty seconds.", "default", ["defeat", "first"], "default = القيمة اللي بتتحط لو ماحددتش.", "«default» = the value used if you set nothing."],
        ["m", "deprecated معناها إيه؟", "What does «deprecated» mean?", ["Old, avoid it, it may be removed", "New and fast", "Required"], 0, "deprecated = متاحة لسه بس هتتشال، ماتستخدمهاش.", "Still there but going away; don't use it."],
        ["m", "optional parameter يعني إيه؟", "What is an optional parameter?", ["You can leave it out.", "You must always send it.", "It is secret."], 0, "optional = اختياري.", "You may leave it out."]] },

  { id: "analyze-docs", t: { ar: "تحلّل توثيق API", en: "Analyzing API documentation" },
    body: { ar: "تقرا endpoint: الـ method والـ URL والـ headers والرد وأكواد الأخطاء. **This endpoint returns…**، **You need to send…**", en: "Read an endpoint: method, URL, headers, response and error codes. **This endpoint returns…**, **You need to send…**" },
    d: [["Sara", "Let's look at the orders API. What does this endpoint return?", "يلا نبص على API الطلبات. الـ endpoint ده بيرجّع إيه؟"],
        ["Karim", "GET /orders returns a list of orders, twenty per page.", "GET /orders بيرجّع ليستة طلبات، عشرين في كل صفحة."],
        ["Sara", "Do we need to send anything?", "محتاجين نبعت حاجة؟"],
        ["Karim", "Yes, you need to send an API key in the Authorization header.", "أيوه، لازم تبعت API key في header اسمه Authorization."],
        ["Sara", "And if the key is wrong?", "ولو المفتاح غلط؟"],
        ["Karim", "You get a 401 error. A 429 means too many requests.", "هيرجعلك خطأ 401. و429 معناها طلبات كتير أوي."]],
    ph: [["This endpoint returns a list of orders.", "الـ endpoint ده بيرجّع ليستة طلبات."], ["You need to send an API key.", "لازم تبعت API key."], ["Twenty per page", "عشرين في الصفحة"], ["A 429 means too many requests.", "429 معناها طلبات كتير أوي."]],
    q: [["f", "You need ___ send an API key.", "to", ["for", "—"], "need to + فعل.", "«need to» + verb."],
        ["f", "It returns twenty orders ___ page.", "per", ["by", "each of"], "per page = في كل صفحة.", "«per page» = for each page."],
        ["f", "This endpoint ___ a list.", "returns", ["return", "is return"], "مفرد → returns.", "Singular subject → «returns»."],
        ["m", "خطأ 401 معناه إيه هنا؟", "What does a 401 mean here?", ["The API key is wrong or missing.", "Too many requests", "The page is empty."], 0, "401 = مش مسموحلك (المفتاح غلط).", "401 = not authorized (bad key)."],
        ["m", "المفتاح بيتبعت فين؟", "Where is the key sent?", ["In the Authorization header", "In the URL", "In the email"], 0, "in the Authorization header.", "«in the Authorization header»."]] },

  { id: "accomplish", t: { ar: "تشارك تقدّمك وإنجازاتك", en: "Sharing progress and accomplishments" },
    body: { ar: "المضارع التام للنتيجة: **We have finished…**، **I've fixed…**، و**so far / already / yet**.", en: "The present perfect for results: **We have finished…**, **I've fixed…**, and **so far / already / yet**." },
    d: [["Manager", "How is the migration going?", "النقل ماشي إزاي؟"],
        ["Adam", "Very well. We've already moved eighty percent of the data.", "كويس جدًا. نقلنا 80% من البيانات بالفعل."],
        ["Manager", "Great! Any problems so far?", "عظيم! فيه مشاكل لحد دلوقتي؟"],
        ["Adam", "Two small ones. I've fixed both of them.", "اتنين صغيرين. صلّحتهم الاتنين."],
        ["Manager", "Have you tested the reports yet?", "اختبرت التقارير ولا لسه؟"],
        ["Adam", "Not yet. I'll test them tomorrow.", "لسه. هختبرها بكره."]],
    ph: [["We've already moved eighty percent.", "نقلنا 80% بالفعل."], ["Any problems so far?", "فيه مشاكل لحد دلوقتي؟"], ["I've fixed both of them.", "صلّحتهم الاتنين."], ["Not yet. I'll test them tomorrow.", "لسه. هختبرها بكره."]],
    q: [["f", "We've ___ moved eighty percent.", "already", ["yet", "still"], "already في الجملة المثبتة = بالفعل.", "«already» in a positive sentence."],
        ["f", "Have you tested the reports ___?", "yet", ["already now", "still"], "yet في آخر السؤال = لحد دلوقتي.", "«yet» ends the question."],
        ["f", "I've ___ both of them.", "fixed", ["fix", "fixing"], "have + التصريف التالت (fixed).", "have + past participle."],
        ["m", "آدم هيختبر التقارير إمتى؟", "When will Adam test the reports?", ["Tomorrow", "Today", "He already did"], 0, "I'll test them tomorrow.", "«I'll test them tomorrow.»"],
        ["m", "أنهي جملة صح؟", "Which sentence is correct?", ["I have finished the task.", "I have finish the task.", "I finished the task yet."], 0, "have + finished.", "have + past participle."]] },

  { id: "plans", t: { ar: "تحديثات وخطط المهام والمشاريع", en: "Updates and plans for tasks and projects" },
    body: { ar: "المستقبل: **going to** للخطة، و**will** للقرار اللحظي، و**by Friday / next sprint**.", en: "The future: **going to** for plans, **will** for a quick decision, and **by Friday / next sprint**." },
    d: [["Tom", "What's the plan for the next sprint?", "إيه الخطة للـ sprint الجاي؟"],
        ["Sofia", "We're going to build the payment page.", "هنبني صفحة الدفع."],
        ["Tom", "When will it be ready?", "هتبقى جاهزة إمتى؟"],
        ["Sofia", "We hope by the end of the month.", "بنتمنى قبل آخر الشهر."],
        ["Tom", "Who's going to write the tests?", "مين هيكتب الاختبارات؟"],
        ["Sofia", "I don't know yet. I'll ask the QA team now.", "لسه مش عارفة. هسأل فريق الـ QA دلوقتي."]],
    ph: [["We're going to build the payment page.", "هنبني صفحة الدفع."], ["When will it be ready?", "هتبقى جاهزة إمتى؟"], ["By the end of the month", "قبل آخر الشهر"], ["I'll ask the QA team now.", "هسأل فريق الـ QA دلوقتي."]],
    q: [["f", "We're going ___ build the payment page.", "to", ["for", "—"], "going to + فعل.", "«going to» + verb."],
        ["f", "When ___ it be ready?", "will", ["is", "does"], "When will it be…? سؤال عن المستقبل.", "«When will it be…?» asks about the future."],
        ["f", "I don't know yet. I___ ask the QA team now.", "'ll", ["'m", "'ve"], "قرار في اللحظة → will.", "A decision made now → «will»."],
        ["m", "إيه الخطة للـ sprint الجاي؟", "What's the plan for the next sprint?", ["The payment page", "The login page", "A new server"], 0, "We're going to build the payment page.", "«…the payment page.»"],
        ["m", "by the end of the month معناها إيه؟", "What does «by the end of the month» mean?", ["Not later than the last day of the month", "After the month", "Every month"], 0, "by = قبل أو في معاد أقصاه.", "«by» = no later than."]] },

  { id: "agree-a2", t: { ar: "توافق أو تعترض ببساطة", en: "Expressing agreement or disagreement" },
    body: { ar: "**I agree / I don't agree**، **You're right**، **I see your point, but…**، بشكل مهذب.", en: "**I agree / I don't agree**, **You're right**, **I see your point, but…**, politely." },
    d: [["Designer", "I think the button should be green, not blue.", "أعتقد إن الزرار لازم يبقى أخضر مش أزرق."],
        ["Dev", "I agree. Green is easier to see.", "موافق. الأخضر أوضح."],
        ["Designer", "And let's put it at the top of the page.", "ويلا نحطه فوق في أول الصفحة."],
        ["Dev", "I see your point, but on phones the top is hard to reach.", "فاهم قصدك، بس على الموبايل فوق صعب توصله."],
        ["Designer", "You're right. What about the bottom?", "عندك حق. طب تحت؟"],
        ["Dev", "That works for me.", "ده مناسب ليّا."]],
    ph: [["I agree.", "موافق."], ["I see your point, but…", "فاهم قصدك، بس…"], ["You're right.", "عندك حق."], ["That works for me.", "ده مناسب ليّا."]],
    q: [["f", "I ___ your point, but phones are different.", "see", ["look", "watch"], "I see your point = فاهم قصدك.", "«I see your point» = I understand you."],
        ["f", "You're ___.", "right", ["agree", "true"], "You're right = عندك حق.", "«You're right» is the phrase."],
        ["f", "I don't ___. Blue is better.", "agree", ["agreed", "agreeing"], "I don't + فعل في أصله.", "«I don't» + base verb."],
        ["m", "أنهي جملة اعتراض مهذب؟", "Which is a polite disagreement?", ["I see your point, but…", "That's stupid.", "No."], 0, "بتعترف برأيه الأول وبعدين بتقول رأيك.", "It accepts their view before giving yours."],
        ["m", "اتفقوا يحطوا الزرار فين؟", "Where do they agree to put the button?", ["At the bottom", "At the top", "In the menu"], 0, "What about the bottom? / That works for me.", "They settle on the bottom."]] },

  { id: "support", t: { ar: "تقدّم دعم فني وإرشاد", en: "Offering technical support and guidance" },
    body: { ar: "في مراجعة كود: **You should…**، **Try…**، **It's a good idea to…**، **Make sure you…**.", en: "In a code review: **You should…**, **Try…**, **It's a good idea to…**, **Make sure you…**." },
    d: [["Senior", "Your code works, nice job. I have a few suggestions.", "الكود شغال، شغل حلو. عندي كام اقتراح."],
        ["Junior", "Sure, please.", "أكيد، اتفضل."],
        ["Senior", "You should give this variable a clearer name. 'x' doesn't say much.", "لازم تدّي الـ variable ده اسم أوضح. x مش بيقول حاجة."],
        ["Senior", "It's a good idea to split this long function into two.", "فكرة كويسة تقسم الـ function الطويلة دي لاتنين."],
        ["Junior", "OK. Anything else?", "تمام. حاجة تانية؟"],
        ["Senior", "Make sure you never put passwords in the code. Use environment variables.", "اتأكد إنك عمرك ما تحط باسوردات في الكود. استخدم environment variables."]],
    ph: [["You should give it a clearer name.", "لازم تدّيه اسم أوضح."], ["It's a good idea to split it.", "فكرة كويسة تقسمها."], ["Make sure you…", "اتأكد إنك…"], ["I have a few suggestions.", "عندي كام اقتراح."]],
    q: [["f", "You ___ give it a clearer name.", "should", ["should to", "must to"], "should + فعل = نصيحة.", "«should» + verb gives advice."],
        ["f", "It's a good idea ___ split it.", "to", ["for", "of"], "It's a good idea to + فعل.", "«It's a good idea to» + verb."],
        ["f", "Make ___ you never put passwords in the code.", "sure", ["certain to", "safe"], "Make sure = اتأكد.", "«Make sure» = check that."],
        ["m", "الباسوردات تتحط فين بدل الكود؟", "Where should passwords go instead of the code?", ["Environment variables", "Comments", "The README"], 0, "Use environment variables.", "«Use environment variables.»"],
        ["m", "ليه x اسم وحش؟", "Why is «x» a bad name?", ["It doesn't say what the value is.", "It is too long.", "It is a keyword."], 0, "'x' doesn't say much.", "It says nothing about the value."]] },

  { id: "guidance", t: { ar: "تطلب إرشاد وتستقبله", en: "Requesting and receiving guidance" },
    body: { ar: "تطلب مساعدة بأدب وتشكر: **Could you help me with…?**، **I'm stuck on…**، **Thanks, that makes sense.**", en: "Ask for help politely and say thanks: **Could you help me with…?**, **I'm stuck on…**, **Thanks, that makes sense.**" },
    d: [["Nour", "Could you help me with a coding challenge? I'm stuck.", "ممكن تساعدني في تحدي برمجة؟ أنا واقفة."],
        ["Ali", "Sure. What have you tried so far?", "أكيد. جرّبتي إيه لحد دلوقتي؟"],
        ["Nour", "I tried two loops, but it's too slow for big lists.", "جربت اتنين loop، بس بطيء أوي مع الليستات الكبيرة."],
        ["Ali", "Try a dictionary. You can find each item in one step.", "جربي dictionary. تقدري تلاقي كل عنصر في خطوة واحدة."],
        ["Nour", "Oh, that makes sense. Thanks a lot!", "آه، كده مفهوم. شكرًا جدًا!"],
        ["Ali", "No problem. Tell me if it works.", "ولا يهمك. قوليلي لو اشتغل."]],
    ph: [["Could you help me with…?", "ممكن تساعدني في…؟"], ["I'm stuck.", "أنا واقف."], ["What have you tried so far?", "جربت إيه لحد دلوقتي؟"], ["That makes sense.", "كده مفهوم."]],
    q: [["f", "Could you help me ___ a challenge?", "with", ["for", "in"], "help someone with something.", "«help someone with» something."],
        ["f", "I'm ___. I don't know what to do.", "stuck", ["stick", "sticking"], "I'm stuck = واقف ومش عارف أكمّل.", "«I'm stuck» = I can't continue."],
        ["f", "That ___ sense.", "makes", ["does", "has"], "make sense تركيبة ثابتة.", "«make sense» is fixed."],
        ["m", "علي اقترح إيه؟", "What does Ali suggest?", ["Use a dictionary", "Use three loops", "Give up"], 0, "Try a dictionary.", "«Try a dictionary.»"],
        ["m", "أنهي سؤال كويس قبل ما تساعد حد؟", "Which question is good before you help someone?", ["What have you tried so far?", "Why are you slow?", "Who are you?"], 0, "بتعرف وصل لفين.", "It shows where they are."]] },

  { id: "explain", t: { ar: "تشرح لحد وإنت بتساعده", en: "Giving explanations when helping others" },
    body: { ar: "خطوات بسيطة وأسباب: **First…, then…**، **This happens because…**، **so…**.", en: "Simple steps and reasons: **First…, then…**, **This happens because…**, **so…**." },
    d: [["Mona", "My laptop is very slow today. Can you take a look?", "اللابتوب بطيء أوي النهارده. ممكن تبص عليه؟"],
        ["Adam", "Sure. First, open the Task Manager.", "أكيد. الأول افتحي الـ Task Manager."],
        ["Mona", "OK. The browser uses ninety percent of the memory!", "تمام. المتصفح واخد تسعين في المية من الذاكرة!"],
        ["Adam", "That happens because you have forty tabs open.", "ده بيحصل عشان عندك أربعين تاب مفتوحة."],
        ["Adam", "Close the tabs you don't need, then restart the browser.", "اقفلي التابات اللي مش محتاجاها، وبعدين اعملي restart للمتصفح."],
        ["Mona", "Wow, it's fast again. Thank you!", "واو، رجع سريع. شكرًا!"]],
    ph: [["First, open the Task Manager.", "الأول افتح الـ Task Manager."], ["That happens because…", "ده بيحصل عشان…"], ["Close the tabs you don't need.", "اقفل التابات اللي مش محتاجها."], ["Then restart the browser.", "وبعدين اعمل restart للمتصفح."]],
    q: [["f", "That happens ___ you have forty tabs open.", "because", ["so", "but"], "because = عشان (السبب).", "«because» gives the reason."],
        ["f", "___, open the Task Manager.", "First", ["Firstly of", "One"], "First = أول خطوة.", "«First» = the first step."],
        ["f", "Close the tabs you don't ___.", "need", ["needs", "needing"], "you don't + فعل في أصله.", "«you don't» + base verb."],
        ["m", "ليه اللابتوب كان بطيء؟", "Why was the laptop slow?", ["Too many browser tabs", "A virus", "No internet"], 0, "forty tabs open.", "Forty tabs were open."],
        ["m", "آخر خطوة كانت إيه؟", "What was the last step?", ["Restart the browser", "Buy a new laptop", "Open more tabs"], 0, "then restart the browser.", "«then restart the browser»."]] }
]});
